# Author: Aditya (boilerplate code generated by Sonnet, refined manually)
# Description: Simple Compartmental SIR Model for AI Malware Tooling Diffusion
# ==========================================
# 1. Model Definitions
# ==========================================
# S = Susceptible (Organizations / endpoints vulnerable to automated exploits)
# I = Infected (Compromised or actively attacked entities)
# R = Recovered / Patched (Air-gapped, zero-trust hardened, or immune)
TOTAL_POPULATION = 100000.0  # Normalized critical enterprise pool
INITIAL_INFECTED = 10.0
INITIAL_RECOVERED = 0.0
INITIAL_SUSCEPTIBLE = TOTAL_POPULATION - INITIAL_INFECTED

# Model parameters
TRANSMISSION_RATE_BETA = 0.35  # Autonomous malware chaining speed
PATCH_RATE_GAMMA = 0.12        # Rate at which defenses deploy patches
DAYS_TO_SIMULATE = 60
TIME_STEP = 0.5                # Half-day step size for Euler approximation

# ==========================================
# 2. Simulation Loop (Euler's Method)
# ==========================================
def simulate_diffusion():
    print(f"Running SIR Malware Diffusion across {DAYS_TO_SIMULATE} days...")
    print(f"Population: {int(TOTAL_POPULATION)} | Beta: {TRANSMISSION_RATE_BETA} | Gamma: {PATCH_RATE_GAMMA}\n")

    current_s = INITIAL_SUSCEPTIBLE
    current_i = INITIAL_INFECTED
    current_r = INITIAL_RECOVERED
    current_day = 0.0
    history = []

    while current_day <= DAYS_TO_SIMULATE:
        # Save daily record
        if round(current_day, 1) % 5 == 0:
            history.append({
                "day": int(current_day),
                "susceptible": int(current_s),
                "infected": int(current_i),
                "recovered": int(current_r)
            })

        # Calculate derivatives (Differential equations)
        # dS/dt = -beta * S * I / N
        # dI/dt = (beta * S * I / N) - (gamma * I)
        # dR/dt = gamma * I
        new_infections = (TRANSMISSION_RATE_BETA * current_s * current_i) / TOTAL_POPULATION
        new_recoveries = PATCH_RATE_GAMMA * current_i

        # Update compartments
        current_s = current_s - (new_infections * TIME_STEP)
        current_i = current_i + ((new_infections - new_recoveries) * TIME_STEP)
        current_r = current_r + (new_recoveries * TIME_STEP)

        # Make sure compartments don't drop below 0
        current_s = max(0.0, current_s)
        current_i = max(0.0, current_i)
        current_r = max(0.0, current_r)

        current_day += TIME_STEP

    # Print results table
    print(f"{'Day':<6} | {'Susceptible (Unpatched)':<24} | {'Active Infections':<20} | {'Patched (Recovered)':<20}")
    print("-" * 80)
    for row in history:
        print(f"{row['day']:<6} | {row['susceptible']:<24} | {row['infected']:<20} | {row['recovered']:<20}")

if __name__ == "__main__":
    simulate_diffusion()
